import type { Metadata } from "next";
import type { SiteContent } from "@/content/site";
import { getSiteUrl } from "./site-url";

const paths = { en: "/", ar: "/ar" } as const;

/** Page metadata (title, description, canonical, language alternates, Open Graph, Twitter). */
export function buildMetadata(c: SiteContent): Metadata {
  const siteUrl = getSiteUrl();
  const path = paths[c.locale];
  // Share image generated by src/app/opengraph-image.tsx / twitter-image.tsx (used by both languages).
  const alt = `${c.site.name} — ${c.site.title}`;
  const image = (route: string) => ({ url: `${siteUrl}${route}`, width: 1200, height: 630, alt, type: "image/png" });

  return {
    metadataBase: new URL(siteUrl),
    title: c.site.meta.title,
    description: c.site.meta.description,
    applicationName: c.site.name,
    authors: [{ name: c.site.name, url: c.site.linkedin }],
    alternates: {
      canonical: path,
      languages: { en: paths.en, ar: paths.ar, "x-default": paths.en },
    },
    openGraph: {
      type: "profile",
      url: path,
      siteName: c.site.name,
      title: c.site.meta.title,
      description: c.site.meta.description,
      locale: c.locale === "ar" ? "ar_JO" : "en_US",
      alternateLocale: c.locale === "ar" ? ["en_US"] : ["ar_JO"],
      images: [image("/opengraph-image")],
    },
    twitter: {
      card: "summary_large_image",
      title: c.site.meta.title,
      description: c.site.meta.description,
      images: [image("/twitter-image")],
    },
    robots: { index: true, follow: true },
  };
}

/** JSON-LD Person schema. */
export function personJsonLd(c: SiteContent) {
  const siteUrl = getSiteUrl();
  return JSON.stringify({
    "@context": "https://schema.org",
    "@type": "Person",
    name: c.site.name,
    jobTitle: c.site.title,
    url: `${siteUrl}${paths[c.locale] === "/" ? "" : paths[c.locale]}`,
    email: `mailto:${c.site.email}`,
    image: `${siteUrl}${c.site.portrait.src}`,
    knowsLanguage: ["ar", "en"],
    address: { "@type": "PostalAddress", addressLocality: "Irbid", addressCountry: "JO" },
    sameAs: [c.site.linkedin],
  }).replace(/</g, "\\u003c");
}
